const incoming = $input.all().map(item => item.json ?? {});
const cfg = $("CONFIG — Edit Me Once").first().json ?? {};

// The Merge node combines the three RSS feeds and the Sheet rows.
// Separate them by their field structure instead of referencing RSS nodes directly.
const memoryKeys = [
  "record_id",
  "record_type",
  "status",
  "post_text",
  "user_idea",
  "voice_example",
  "approval"
];

const rows = incoming.filter(item =>
  item &&
  typeof item === "object" &&
  memoryKeys.some(key =>
    Object.prototype.hasOwnProperty.call(item, key)
  )
);

const rss = incoming.filter(item =>
  item &&
  typeof item === "object" &&
  (typeof item.title === "string" ||
   typeof item.link === "string")
);

// Avoid repeating recently published topics and posts.
const published = rows
  .filter(r =>
    String(r.status || "").toUpperCase() === "PUBLISHED" &&
    r.post_text
  );

const recentPosts = published
  .slice(-25)
  .map(r => ({
    topic: r.topic || "",
    angle: r.angle || "",
    post: r.post_text || ""
  }));

// Real examples of your own writing, if added to the Sheet.
const voice = rows
  .filter(r =>
    String(r.record_type || "").toUpperCase() === "VOICE_EXAMPLE" &&
    r.voice_example
  )
  .slice(-10)
  .map(r => r.voice_example);

// Raw ideas you have added to the Sheet.
const ideas = rows
  .filter(r =>
    String(r.record_type || "").toUpperCase() === "IDEA" &&
    (!r.status || r.status === "NEW")
  )
  .slice(-10)
  .map(r => ({
    idea: r.user_idea,
    id: r.record_id
  }));

// The RSS feeds are appended in sequence by the Merge node.
// Sample across all three feeds rather than only taking the first feed.
const chunkSize = Math.ceil(rss.length / 3);
const feeds = [
  rss.slice(0, chunkSize),
  rss.slice(chunkSize, chunkSize * 2),
  rss.slice(chunkSize * 2)
];

const balanced = [];

for (let i = 0; i < chunkSize; i++) {
  for (const feed of feeds) {
    if (feed[i]) balanced.push(feed[i]);
  }
}

const trendCandidates = balanced
  .filter(item => item.title || item.link)
  .map(item => ({
    title: String(item.title || "").trim(),
    link: String(item.link || "").trim(),
    date: String(item.pubDate || item.isoDate || ""),
    source: String(item.creator || item.source || ""),
    snippet: String(
      item.contentSnippet || item.content || ""
    ).replace(/\s+/g, " ").slice(0, 700)
  }))
  .slice(0, 40);

return [{
  json: {
    now: new Date().toISOString(),
    contentPillars: cfg.content_pillars || "",
    voiceGuidance: cfg.voice_examples || "",
    recentPosts,
    voice,
    ideas,
    trendCandidates
  }
}];

