function extractAIResult(nodeName, expectedKeys) {
  const raw = $(nodeName).first().json;
  const queue = [raw];
  const visited = new Set();
  let checked = 0;

  while (queue.length > 0 && checked < 1000) {
    const value = queue.shift();
    checked++;

    if (value == null) continue;

    if (typeof value === "string") {
      const cleaned = value
        .trim()
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/i, "");

      if (
        cleaned.startsWith("{") ||
        cleaned.startsWith("[")
      ) {
        try {
          queue.unshift(JSON.parse(cleaned));
          continue;
        } catch {
          // Try extracting a JSON object from surrounding text.
          const start = cleaned.indexOf("{");
          const end = cleaned.lastIndexOf("}");

          if (start !== -1 && end > start) {
            try {
              queue.unshift(
                JSON.parse(cleaned.slice(start, end + 1))
              );
              continue;
            } catch {
              // Continue searching the remaining response.
            }
          }
        }
      }

      continue;
    }

    if (typeof value !== "object") continue;
    if (visited.has(value)) continue;
    visited.add(value);

    if (Array.isArray(value)) {
      queue.push(...value);
      continue;
    }

    // Return the parsed AI result when expected fields exist.
    if (
      expectedKeys.some(key =>
        Object.prototype.hasOwnProperty.call(value, key)
      )
    ) {
      return value;
    }

    // Traverse nested n8n/OpenAI response wrappers.
    for (const child of Object.values(value)) {
      if (child !== null && child !== undefined) {
        queue.push(child);
      }
    }
  }

  throw new Error(
    `Could not extract structured AI output from "${nodeName}". ` +
    `Expected fields: ${expectedKeys.join(", ")}`
  );
}

function toBoolean(value) {
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    return value.trim().toLowerCase() === "true";
  }
  return Boolean(value);
}

// 1. Read outputs from all three AI nodes.
const research = extractAIResult(
  "AI Research + Topic Selector",
  ["topic", "angle", "source_url", "why_now"]
);

const writer = extractAIResult(
  "AI Writer — Humanized Draft",
  ["post", "needs_image", "image_prompt"]
);

const qa = extractAIResult(
  "AI QA — Humanization + Fact Check",
  [
    "final_post",
    "edited_post",
    "post",
    "score",
    "original_score",
    "pass"
  ]
);

// 2. Choose the final post.
// Your QA node returns "edited_post" when it rewrites a weak draft.
const post = String(
  qa.final_post ||
  qa.edited_post ||
  qa.post ||
  writer.post ||
  writer.final_post ||
  ""
).trim();

if (!post) {
  throw new Error(
    "No post text found. Check the text output of AI Writer " +
    "and AI QA, including the edited_post field."
  );
}

// 3. Read image requirements safely.
const needsImage = toBoolean(
  qa.final_needs_image ??
  writer.needs_image ??
  qa.needs_image ??
  false
);

const imagePrompt = String(
  qa.final_image_prompt ||
  writer.image_prompt ||
  ""
).trim();

// 4. Read configuration.
const config = $("CONFIG — Edit Me Once").first().json;

if (!config.sheet_id) {
  throw new Error(
    "Google Sheet ID is missing from CONFIG — Edit Me Once."
  );
}

if (!config.sheet_name) {
  throw new Error(
    "Google Sheet tab name is missing from CONFIG — Edit Me Once."
  );
}

if (!config.telegram_chat_id) {
  throw new Error(
    "Telegram chat ID is missing from CONFIG — Edit Me Once."
  );
}

if (!config.linkedin_person_id) {
  throw new Error(
    "LinkedIn person identifier is missing from CONFIG — Edit Me Once."
  );
}

// 5. Prepare the source summary.
const facts = Array.isArray(research.facts)
  ? research.facts
  : research.facts
    ? [research.facts]
    : [];

const sourceSummary = [
  research.why_now,
  ...facts
].filter(Boolean).join(" ");

// 6. Create one unique ID for this draft.
const randomSuffix = Math.random()
  .toString(36)
  .slice(2, 8)
  .toUpperCase()
  .padEnd(6, "0");

const recordId = `LI-${Date.now()}-${randomSuffix}`;

// 7. Output one structured row for Google Sheets.
return [
  {
    json: {
      record_id: recordId,
      record_type: "POST",
      created_at: new Date().toISOString(),
      status: "APPROVAL_PENDING",

      topic: research.topic || "AI and automation",
      angle: research.angle || "",
      source_url: research.source_url || "",
      source_summary: sourceSummary,

      post_text: post,
      needs_image: needsImage,
      image_prompt: imagePrompt,

      approval: "",
      approval_comment: "",
      version: 1,
      retry_count: 0,

      // Supports both QA response formats.
      qa_score: Number(
        qa.score ?? qa.original_score ?? 0
      ),
      qa_passed: toBoolean(qa.pass ?? false),

      telegram_chat_id: String(config.telegram_chat_id),
      linkedin_person_id: String(config.linkedin_person_id),

      published_at: "",
      linkedin_post_id: "",
      linkedin_url: "",
      error: "",
      voice_example: "",
      user_idea: ""
    }
  }
];

